import{_ as i,o as e,c as t,a2 as s}from"./chunks/framework.z3u3TMv0.js";const k=JSON.parse('{"title":"A1111（SD WebUI）のインストール","description":"AUTOMATIC1111 Stable Diffusion WebUI をインストールし、--api と LAN を有効化して MiniTavern 画像接続へ。","frontmatter":{"title":"A1111（SD WebUI）のインストール","description":"AUTOMATIC1111 Stable Diffusion WebUI をインストールし、--api と LAN を有効化して MiniTavern 画像接続へ。","head":[["meta",{"name":"keywords","content":"酒場,AI酒場,MiniTavern,AI相棒,AI友達,AIローカルチャット,Silly Tavern,SillyTavern,スマホでSilly Tavern,Silly Tavernスマホ版,Silly Tavern Android,Silly Tavern iOS,AIロールプレイ,キャラクターカード,AIチャット,スマホAI,オフラインAI,AIストーリー,ローカルLLM,Ollama,LM Studio,ワールドブック,正規表現,BYOK,ユーザーガイド,マニュアル"}],["meta",{"property":"og:title","content":"A1111（SD WebUI）のインストール · MiniTavern Docs"}],["meta",{"property":"og:description","content":"AUTOMATIC1111 Stable Diffusion WebUI をインストールし、--api と LAN を有効化して MiniTavern 画像接続へ。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ja/local/image-gen/a1111"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ja/local/image-gen/a1111"}]]},"headers":[],"relativePath":"ja/local/image-gen/a1111.md","filePath":"ja/local/image-gen/a1111.md","lastUpdated":1787224147000}'),n={name:"ja/local/image-gen/a1111.md"};function l(h,a,o,p,d,r){return e(),t("div",null,[...a[0]||(a[0]=[s(`<h1 id="a1111-sd-webui-のインストール" tabindex="-1">A1111（SD WebUI）のインストール <a class="header-anchor" href="#a1111-sd-webui-のインストール" aria-label="Permalink to &quot;A1111（SD WebUI）のインストール&quot;">​</a></h1><p>AUTOMATIC1111（通称 <strong>A1111／SD WebUI</strong>）はブラウザ UI と REST API（<code>/sdapi/v1/txt2img</code>）を提供。<br> MiniTavern の <strong>A1111(SD WebUI)</strong> プラットフォームがこの API に接続；<strong>SD.Next</strong> など同プロトコルも試せる。</p><p>公式倉庫：<a href="https://github.com/AUTOMATIC1111/stable-diffusion-webui" target="_blank" rel="noreferrer">AUTOMATIC1111/stable-diffusion-webui</a></p><h2 id="ハードウェア推奨" tabindex="-1">ハードウェア推奨 <a class="header-anchor" href="#ハードウェア推奨" aria-label="Permalink to &quot;ハードウェア推奨&quot;">​</a></h2><table tabindex="0"><thead><tr><th>显存</th><th>推奨</th></tr></thead><tbody><tr><td>6GB</td><td>SD 1.5、小さめ解像度</td></tr><tr><td>8GB+</td><td>SDXL がより安定</td></tr><tr><td>CPU のみ</td><td>動くが極遅、検証用</td></tr></tbody></table><h2 id="windows-入門推奨" tabindex="-1">Windows（入門推奨） <a class="header-anchor" href="#windows-入門推奨" aria-label="Permalink to &quot;Windows（入門推奨）&quot;">​</a></h2><h3 id="_1-依存のインストール" tabindex="-1">1. 依存のインストール <a class="header-anchor" href="#_1-依存のインストール" aria-label="Permalink to &quot;1. 依存のインストール&quot;">​</a></h3><ol><li><a href="https://git-scm.com/download/win" target="_blank" rel="noreferrer">Git for Windows</a> をインストール。</li><li><a href="https://www.python.org/downloads/" target="_blank" rel="noreferrer">Python 3.10.x</a> をインストール（<strong>Add python.exe to PATH</strong> にチェック）。</li><li>新しい <strong>NVIDIA ドライバ</strong>推奨（NVIDIA GPU がある場合）。</li></ol><h3 id="_2-webui-の取得" tabindex="-1">2. WebUI の取得 <a class="header-anchor" href="#_2-webui-の取得" aria-label="Permalink to &quot;2. WebUI の取得&quot;">​</a></h3><p>適当なディレクトリ（例 <code>D:\\AI</code>）で PowerShell：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git clone https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AUTOMATIC1111</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diffusion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui.git</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd stable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">diffusion</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">webui</span></span></code></pre></div><h3 id="_3-初回起動" tabindex="-1">3. 初回起動 <a class="header-anchor" href="#_3-初回起動" aria-label="Permalink to &quot;3. 初回起動&quot;">​</a></h3><p>ダブルクリックまたは端末で：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">webui-user.bat</span></span></code></pre></div><p>初回は依存と基盤コンポーネントの自動取得で時間がかかる。完了後ブラウザはだいたい：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7860</span></span></code></pre></div><h3 id="_4-api-lan-スマホ接続に必須" tabindex="-1">4. API＋LAN（スマホ接続に必須） <a class="header-anchor" href="#_4-api-lan-スマホ接続に必須" aria-label="Permalink to &quot;4. API＋LAN（スマホ接続に必須）&quot;">​</a></h3><p>同ディレクトリの <code>webui-user.bat</code> を編集し、<code>COMMANDLINE_ARGS</code> 行を例えば：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMANDLINE_ARGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--api --listen</span></span></code></pre></div><p>説明：</p><table tabindex="0"><thead><tr><th>パラメータ</th><th>作用</th></tr></thead><tbody><tr><td><code>--api</code></td><td><code>/sdapi/v1/*</code> を有効化（<strong>MiniTavern 必須</strong>）</td></tr><tr><td><code>--listen</code></td><td><code>0.0.0.0</code> をリスンし、LAN デバイスを許可</td></tr><tr><td><code>--port 7860</code></td><td>任意；ポート変更時は App も合わせる</td></tr></tbody></table><p>保存後、<code>webui-user.bat</code> を再実行。</p><p>任意：<code>--api-auth ユーザー名:パスワード</code> で API に認証；有効時は App 画像接続の API Key／認証欄を実装に合わせて記入（現行 App 文案準拠）。</p><h3 id="_5-api-の検証" tabindex="-1">5. API の検証 <a class="header-anchor" href="#_5-api-の検証" aria-label="Permalink to &quot;5. API の検証&quot;">​</a></h3><p>本機ブラウザで：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:7860/docs</span></span></code></pre></div><p>Swagger が見えれば API は開通。LAN 検証（IP を PC の IP に）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://192.168.x.x:7860/docs</span></span></code></pre></div><h2 id="macos-linux-要約" tabindex="-1">macOS／Linux 要約 <a class="header-anchor" href="#macos-linux-要約" aria-label="Permalink to &quot;macOS／Linux 要約&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/AUTOMATIC1111/stable-diffusion-webui.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stable-diffusion-webui</span></span></code></pre></div><p><code>webui-user.sh</code> を編集：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COMMANDLINE_ARGS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--api --listen&quot;</span></span></code></pre></div><p>その後 <code>./webui.sh</code>。Apple Silicon 可、速度は同級 NVIDIA より遅いことが多い。</p><h2 id="モデル-checkpoint-の取得" tabindex="-1">モデル（Checkpoint）の取得 <a class="header-anchor" href="#モデル-checkpoint-の取得" aria-label="Permalink to &quot;モデル（Checkpoint）の取得&quot;">​</a></h2><ol><li><a href="https://civitai.com/" target="_blank" rel="noreferrer">Civitai</a> または <a href="https://huggingface.co/" target="_blank" rel="noreferrer">Hugging Face</a> から <code>.safetensors</code> をダウンロード。</li><li>配置先：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stable-diffusion-webui/models/Stable-diffusion/</span></span></code></pre></div><ol start="3"><li>WebUI 左上で更新してモデル選択；または WebUI 再起動。</li></ol><p>入門は先に SD 1.5 または SDXL 汎用モデルを入れ、WebUI で手動出図できることを確認してから App 接続。</p><h2 id="ファイアウォール" tabindex="-1">ファイアウォール <a class="header-anchor" href="#ファイアウォール" aria-label="Permalink to &quot;ファイアウォール&quot;">​</a></h2><p>Windows：初回リスン時にプライベートネットワークを許可、またはファイアウォールでポート <strong>7860</strong> を開放。<br> スマホは PC と同一 LAN；ゲスト Wi‑Fi はクライアント隔離が多い。</p><h2 id="次のステップ" tabindex="-1">次のステップ <a class="header-anchor" href="#次のステップ" aria-label="Permalink to &quot;次のステップ&quot;">​</a></h2><ul><li><a href="./connect-app">MiniTavern で設定</a>（プラットフォーム A1111、Base URL に PC の LAN アドレス）</li><li>対照：<a href="./index">画像モデル配備</a> · App 内 <a href="/ultra_guides/ja/manual/model-link">モデル接続 · 画像生成</a></li></ul>`,42)])])}const b=i(n,[["render",l]]);export{k as __pageData,b as default};
